+        for (var index = 0; index <= stageIndex; index++)
+        {
+            Assert("graph.history", history[index].ValueKind == JsonValueKind.String && history[index].GetString() == Stages[index],
+                $"Effective release history entry {index} must be {Stages[index]}.");
